import {hairStyles,tops,bottoms,choosePlayerLook,syncOutfits} from './outfits.js';
import {playerItems,playerColors,buyPlayerItem} from './player.js';
import {createPlayerPreview} from './player-model.js';
export function createUnifiedStore({boutique,state,inv,save,refresh,progress,message,miloPanel}){const $=id=>document.getElementById(id);let preview,face=true;function draw(){try{preview??=createPlayerPreview($('playerCanvas'));preview.draw(state,face);$('playerPreviewError').hidden=true;}catch{$('playerPreviewError').hidden=false;}}
function render(){if(syncOutfits(state,progress()))save();const list=$('playerChoices');list.replaceChildren();$('shopBalance').textContent='💎 '+inv.gems+' diamants';for(const[category,title,items]of [['hair','Cheveux',hairStyles],['top','Haut du corps',tops],['bottom','Bas du corps',bottoms]]){const section=document.createElement('section'),heading=document.createElement('h3');heading.textContent=title;section.append(heading);for(const item of items){const b=document.createElement('button'),locked=item.unlock&&!state.owned.includes(item.unlock);b.textContent=item.name+(locked?' 🔒':state[category]===item.id?' ✓':'');b.setAttribute('aria-pressed',String(state[category]===item.id));b.disabled=!!locked;b.onclick=()=>{if(choosePlayerLook(state,category,item.id)){refresh();save();render();}};section.append(b);}list.append(section);}const colors=document.createElement('section');for(const[color,i]of playerColors.map((c,i)=>[c,i])){const b=document.createElement('button');b.textContent='Couleur du T-shirt '+(i+1);b.style.background=color;b.setAttribute('aria-pressed',String(state.color===color));b.onclick=()=>{state.color=color;state.top='tee';refresh();save();render();};colors.append(b);}list.append(colors);const accessories=document.createElement('section');for(const item of playerItems){const owned=state.owned.includes(item.id),b=document.createElement('button');b.textContent=item.name+' · '+(owned?(state.accessory===item.id?'Retirer':'Porter'):item.price+' 💎');b.disabled=!owned&&inv.gems<item.price;b.onclick=()=>{if(!owned&&!buyPlayerItem(state,inv,item.id))return;state.accessory=state.accessory===item.id?'':item.id;refresh();save();render();};accessories.append(b);}list.append(accessories);draw();}
function tab(player){$('playerStorePanel').hidden=!player;$('shopBody').hidden=player;$('shopEmpty').hidden=player;$('storePlayerTab').setAttribute('aria-selected',String(player));$('storeAnimalTab').setAttribute('aria-selected',String(!player));if(player)render();else boutique.open();}
$('storePlayerTab').onclick=()=>tab(true);$('storeAnimalTab').onclick=()=>tab(false);$('playerFace').onclick=()=>{face=!face;$('playerFace').textContent=face?'↻ Vue de côté':'🙂 Voir de face';draw();};
return {open(){if(!boutique.open())return;tab(true);miloPanel?.render();}};}
